import * as THREE from 'three/webgpu';
import {
  attribute,
  color,
  time,
  sin,
  float,
  vec3,
  mix,
  positionLocal,
  cameraPosition,
  positionWorld,
  smoothstep,
} from 'three/tsl';
import { createMSDFText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'nova-atelier-particle-constellation-hero';
  group.userData.handlers = {};

  const visualColors = (config && config.visual && config.visual.colors) || {};
  const PAPER = visualColors.paper || '#e8ecf2';
  const ACCENT = visualColors.accent || '#ff2a38';
  const BACKGROUND = visualColors.background || '#0b0b10';

  const typography = (config && config.visual && config.visual.typography) || {};

  function getText(role, fallback) {
    const list = (config && config.textContent) || [];
    const entry = Array.isArray(list)
      ? list.find((t) => t && (t.role === role || t.type === role))
      : null;
    return entry && entry.text ? entry.text : fallback;
  }

  // ---------------------------------------------------------------------
  // Instance layout
  // ---------------------------------------------------------------------
  const TOTAL_COUNT = 1200;
  const CORE_COUNT = 90;
  const FIELD_COUNT = TOTAL_COUNT - CORE_COUNT;

  const PARTICLE_RADIUS = 0.012;
  const SHELL_SEMI_AXES = new THREE.Vector3(3.0, 2.0, 2.5); // half of 6x4x5
  const SHELL_CENTER = new THREE.Vector3(0, 0, -1.5);
  const CORE_RADIUS = 0.5;

  const dummy = new THREE.Object3D();
  const tmpPos = new THREE.Vector3();

  function sampleShellPoint(target) {
    const u = Math.random();
    const v = Math.random();
    const theta = 2 * Math.PI * u;
    const phi = Math.acos(2 * v - 1);
    const sx = Math.sin(phi) * Math.cos(theta);
    const sy = Math.sin(phi) * Math.sin(theta);
    const sz = Math.cos(phi);
    const shellR = 0.82 + Math.random() * 0.18; // shell thickness band
    target.set(
      SHELL_CENTER.x + sx * SHELL_SEMI_AXES.x * shellR,
      SHELL_CENTER.y + sy * SHELL_SEMI_AXES.y * shellR,
      SHELL_CENTER.z + sz * SHELL_SEMI_AXES.z * shellR
    );
    return target;
  }

  function sampleCorePoint(target) {
    const r = CORE_RADIUS * Math.cbrt(Math.random());
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);
    target.set(
      r * Math.sin(phi) * Math.cos(theta),
      r * Math.sin(phi) * Math.sin(theta),
      r * Math.cos(phi)
    );
    return target;
  }

  // ---------------------------------------------------------------------
  // Shared TSL helpers
  // ---------------------------------------------------------------------
  const DRIFT_FREQ = float(2 * Math.PI * 0.05); // 0.05 Hz orbit
  const DRIFT_AMOUNT = 0.04;

  function makeDriftOffset(phaseNode) {
    const t = time.mul(DRIFT_FREQ);
    const dx = sin(t.add(phaseNode)).mul(DRIFT_AMOUNT);
    const dy = sin(t.mul(1.31).add(phaseNode.mul(1.7))).mul(DRIFT_AMOUNT);
    const dz = sin(t.mul(0.73).add(phaseNode.mul(2.3))).mul(DRIFT_AMOUNT);
    return vec3(dx, dy, dz);
  }

  const fogFactor = cameraPosition.sub(positionWorld).length().smoothstep
    ? smoothstep(float(4), float(10), cameraPosition.sub(positionWorld).length())
    : smoothstep(float(4), float(10), cameraPosition.sub(positionWorld).length());

  // ---------------------------------------------------------------------
  // Field particles (self-lit paper, depth falloff, atmospheric fog mix)
  // ---------------------------------------------------------------------
  const fieldGeo = new THREE.IcosahedronGeometry(PARTICLE_RADIUS, 0);
  const fieldOpacity = new Float32Array(FIELD_COUNT);
  const fieldPhase = new Float32Array(FIELD_COUNT);

  const fieldMat = new THREE.MeshStandardNodeMaterial({
    roughness: 1,
    metalness: 0,
    transparent: true,
    depthWrite: false,
  });

  const fieldMesh = new THREE.InstancedMesh(fieldGeo, fieldMat, FIELD_COUNT);
  fieldMesh.name = 'field-particles';
  fieldMesh.frustumCulled = false;

  for (let i = 0; i < FIELD_COUNT; i++) {
    sampleShellPoint(tmpPos);
    dummy.position.copy(tmpPos);
    dummy.rotation.set(0, 0, 0);
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    fieldMesh.setMatrixAt(i, dummy.matrix);

    const t = THREE.MathUtils.clamp(-tmpPos.z / 5, 0, 1);
    fieldOpacity[i] = THREE.MathUtils.lerp(0.9, 0.15, t);
    fieldPhase[i] = Math.random() * Math.PI * 2;
  }
  fieldMesh.instanceMatrix.needsUpdate = true;

  fieldGeo.setAttribute('aOpacity', new THREE.InstancedBufferAttribute(fieldOpacity, 1));
  fieldGeo.setAttribute('aPhase', new THREE.InstancedBufferAttribute(fieldPhase, 1));

  fieldMat.colorNode = mix(color(PAPER), color(BACKGROUND), fogFactor);
  fieldMat.emissiveNode = color(PAPER).mul(0.9);
  fieldMat.opacityNode = attribute('aOpacity');
  fieldMat.positionNode = positionLocal.add(makeDriftOffset(attribute('aPhase')));

  group.add(fieldMesh);

  // ---------------------------------------------------------------------
  // Accent core (additive glow, hard-capped emissive pulse)
  // ---------------------------------------------------------------------
  const coreGeo = new THREE.IcosahedronGeometry(PARTICLE_RADIUS, 0);
  const corePhase = new Float32Array(CORE_COUNT);

  const coreMat = new THREE.MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.2,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  });

  const coreMesh = new THREE.InstancedMesh(coreGeo, coreMat, CORE_COUNT);
  coreMesh.name = 'core-particles';
  coreMesh.frustumCulled = false;

  for (let i = 0; i < CORE_COUNT; i++) {
    sampleCorePoint(tmpPos);
    dummy.position.copy(tmpPos);
    dummy.rotation.set(0, 0, 0);
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    coreMesh.setMatrixAt(i, dummy.matrix);
    corePhase[i] = Math.random() * Math.PI * 2;
  }
  coreMesh.instanceMatrix.needsUpdate = true;

  coreGeo.setAttribute('aPhase', new THREE.InstancedBufferAttribute(corePhase, 1));

  const corePulseFreq = float(2 * Math.PI * 0.1); // 0.1 Hz pulse
  const corePulse = mix(float(1.5), float(1.8), sin(time.mul(corePulseFreq)).mul(0.5).add(0.5));

  coreMat.colorNode = color(ACCENT);
  coreMat.emissiveNode = color(ACCENT).mul(corePulse);
  coreMat.positionNode = positionLocal.add(makeDriftOffset(attribute('aPhase')));

  group.add(coreMesh);

  // ---------------------------------------------------------------------
  // Supplementary lights (kept minimal — glow discipline is emissive-driven)
  // ---------------------------------------------------------------------
  const ambientLight = new THREE.AmbientLight(new THREE.Color(PAPER), 0.18);
  const coreLight = new THREE.PointLight(new THREE.Color(ACCENT), 1.3, 6, 2);
  coreLight.position.set(0, 0, 0);
  group.add(ambientLight, coreLight);

  // ---------------------------------------------------------------------
  // MSDF text (hero / subhead / caption) — real font atlas, no TextGeometry
  // ---------------------------------------------------------------------
  const heroCfg = typography.hero || {};
  const subheadCfg = typography.subhead || {};
  const captionCfg = typography.caption || {};

  const heroText = createMSDFText({
    text: getText('hero', 'NOVA ATELIER'),
    fontAtlas: ctx.fontAtlas,
    fontFamily: heroCfg.family || 'Lora',
    fontWeight: heroCfg.fontWeight || 600,
    size: 0.62,
    letterSpacing: heroCfg.letterSpacing ?? -0.01,
    lineHeight: heroCfg.lineHeight ?? 1.02,
    color: PAPER,
    align: 'center',
    anchorX: 'center',
    anchorY: 'middle',
  });
  heroText.name = 'hero-text';
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subheadText = createMSDFText({
    text: getText('subhead', 'Precision instruments for the dark hours.'),
    fontAtlas: ctx.fontAtlas,
    fontFamily: subheadCfg.family || 'JetBrains Mono',
    fontWeight: subheadCfg.fontWeight || 400,
    size: 0.2,
    letterSpacing: subheadCfg.letterSpacing ?? 0.02,
    lineHeight: subheadCfg.lineHeight ?? 1.35,
    color: PAPER,
    align: 'center',
    anchorX: 'center',
    anchorY: 'middle',
  });
  subheadText.name = 'subhead-text';
  subheadText.position.set(0, -0.25, 0.5);
  group.add(subheadText);

  const captionText = createMSDFText({
    text: getText('caption', 'EST. 2019 / GENEVA AND KYOTO'),
    fontAtlas: ctx.fontAtlas,
    fontFamily: captionCfg.family || 'JetBrains Mono',
    fontWeight: captionCfg.fontWeight || 400,
    size: 0.09,
    letterSpacing: captionCfg.letterSpacing ?? 0.08,
    lineHeight: captionCfg.lineHeight ?? 1.4,
    color: PAPER,
    align: 'center',
    anchorX: 'center',
    anchorY: 'middle',
  });
  captionText.name = 'caption-text';
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // ---------------------------------------------------------------------
  // Cinematic primitives — applied through ctx.primitives ONLY
  // ---------------------------------------------------------------------
  const primitiveHandles = [];
  const primitiveList = (config && config.cinematicPrimitives) || [];
  for (const prim of primitiveList) {
    const applyFn = ctx.primitives && ctx.primitives[prim.name];
    if (typeof applyFn === 'function') {
      const handle = applyFn(group, prim.params || {});
      if (handle && typeof handle.kill === 'function') {
        primitiveHandles.push(handle);
      }
    }
  }

  // ---------------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------------
  function disposeDeep(obj) {
    if (!obj) return;
    obj.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        const materials = Array.isArray(child.material) ? child.material : [child.material];
        materials.forEach((m) => {
          if (m.map) m.map.dispose();
          if (m.dispose) m.dispose();
        });
      }
    });
  }

  group.userData.cleanup = () => {
    primitiveHandles.forEach((h) => h.kill());

    fieldMesh.instanceMatrix && fieldMesh.dispose && fieldMesh.dispose();
    coreMesh.dispose && coreMesh.dispose();

    fieldGeo.dispose();
    coreGeo.dispose();
    fieldMat.dispose();
    coreMat.dispose();

    disposeDeep(heroText);
    disposeDeep(subheadText);
    disposeDeep(captionText);

    group.remove(fieldMesh, coreMesh, ambientLight, coreLight, heroText, subheadText, captionText);
  };

  return group;
}
